package dao;import model.*;import java.sql.*;import java.util.*;
public class ScreeningDAO5 extends DAO5{public ScreeningDAO5(Connection c){super(c);}public Screening5[] getScreenings(Movie5 m)throws Exception{List<Screening5>a=query(Screening5.class,"SELECT * FROM tblScreening5 WHERE tblMovie5id=? AND TrangThai='MO_BAN' AND GioBatDau>NOW() ORDER BY GioBatDau",m.getId());for(Screening5 s:a)s.setPhim(m);return a.toArray(new Screening5[0]);}public Screening5 get(int id)throws Exception{try(PreparedStatement p=stmt("SELECT * FROM tblScreening5 WHERE id=?",id);ResultSet r=p.executeQuery()){if(!r.next())throw new IllegalArgumentException("Suất chiếu không tồn tại");Screening5 s=map(r,Screening5.class);s.setPhim(new MovieDAO5(con).get(r.getInt("tblMovie5id")));return s;}}}
